1707		There exists a function $\delta_{\mathrm{Line}}(\eps) = \poly(\eps)$
1708		such that the following holds, with respect to the state
1709		$\ket{\hat{\psi}}$ of Definition~\ref{def:expanded-state}. For all
1710		$W \in \{X,Z\}$ and lines $\ell$ there exists a projective measurement
1711		$\{\hat{M}^{(\mathrm{Line},W),\ell}_f\}_{f \in \deg_{md}(\ell)}$,
1712		acting on registers $\mathsf{A}\mathsf{A}'$ or
1713		$\mathsf{B}\mathsf{A}''$, such that:
1714		\begin{enumerate}
1715			\item \label{enu:qld-comm-line-self-cons}
1716			(\textbf{Self-consistency}) For all $W \in \{X,Z\}$ and
1717			$r \in \F_q$ (the relation does not depend on $r$), on average over
1718			a uniformly random pair $(\ell,u)$ drawn from the line-point
1719			distribution (Definition~\ref{def:line-point-dist}),
1720			\[
1721				(\hat{M}^{(\mathrm{Line},W),\ell}_f)_{\mathsf{A}\mathsf{A}'}
1722				\,\approx_{\delta_{\mathrm{Line}}}\,
1723				(\hat{M}^{(\mathrm{Line},W),\ell}_f)_{\mathsf{B}\mathsf{A}''}\,,
1724			\]
1725			where the answer summation is over $f \in \deg_{md}(\ell)$.
1726			\item \label{eq:qld-comm-line-pt-cons}
1727			(\textbf{Consistency with points measurements I}) On average over
1728			a uniformly random pair $(\ell,u)$ drawn from the line-point
1729			distribution,
1730			\[
1731				(\hat{M}^{(\mathrm{Line},W),\ell}_f)_{\mathsf{A}\mathsf{A}'}
1732				\,\approx_{\delta_{\mathrm{Line}}}\,
1733				(\hat{M}^{(\mathrm{Line},W),\ell}_f)_{\mathsf{A}\mathsf{A}'}
1734				\ot (\hat{M}^{(\mathrm{Point},W),u}_{f(u)})_{\mathsf{B}\mathsf{A}''}\,,
1735			\]
1736			where the answer summation is over $f \in \deg_{md}(\ell)$.
1737			\item \label{eq:qld-comm-line-pt-cons2}
